(()=>{
 const q=s=>document.querySelector(s),feedback=q('#status'),form=q('#retention-form'),oauth=q('#oauth-form');let busy=false,snapshot=null;
 async function api(path='',method='GET',payload){const response=await fetch('/api/admin/archive-settings'+path,{method,cache:'no-store',headers:method==='GET'?{}:{'X-Requested-With':'KrugPi','Content-Type':'application/json'},...(payload?{body:JSON.stringify(payload)}:{})});const result=await response.json();if(!response.ok)throw Error(typeof result.detail==='string'?result.detail:'Не удалось выполнить действие.');return result;}
 function freeze(value){busy=value;document.querySelectorAll('#settings-content button,#settings-content input').forEach(node=>node.disabled=value);if(!value&&snapshot){q('#connect').disabled=!snapshot.configured;q('#cleanup-run').disabled=!snapshot.deletion_enabled;}}
 function render(data){snapshot=data;q('#cleanup-badge').textContent=data.deletion_enabled?'Автоочистка включена':'Удаление выключено';q('#cleanup-enabled').checked=data.deletion_enabled;q('#cleanup-run').disabled=!data.deletion_enabled;q('#cleanup-state').textContent=(data.deletion_enabled?'Очистка включена.':'Очистка выключена.')+(data.cleanup_last_finished?' Последний запуск: '+new Date(data.cleanup_last_finished*1000).toLocaleString('ru-RU')+'.':'')+(data.cleanup_result?' Обработано: '+data.cleanup_result.processed+', очищено: '+data.cleanup_result.cleaned+', ошибок: '+data.cleanup_result.errors+'.':'');oauth.elements.client_id.value=data.client_id||'';oauth.elements.redirect_uri.value=data.redirect_uri||location.origin+'/api/admin/archive-settings/callback';oauth.elements.client_secret.value='';oauth.elements.client_secret.required=!data.secret_saved;q('#secret-state').textContent=data.secret_saved?'Секрет сохранён на сервере. Оставьте поле пустым, чтобы сохранить его, или введите новый для замены.':'Введите Client Secret из Google Cloud. После сохранения он не будет отображаться.';if(!data.configured)q('#oauth-parameters').open=true;q('#drive-state').textContent=data.connected?'Подключён':'Не подключён';q('#drive-account').textContent=data.connected?'Аккаунт: '+(data.email||'Google'):'Подключите диск, на котором будут храниться архивы.';q('#connect').textContent=data.connected?'Переподключить':'Подключить Google Диск';q('#test').hidden=q('#disconnect').hidden=!data.connected;q('#drive-folder').hidden=!data.folder_id;if(data.folder_id){q('#drive-folder-link').href='https://drive.google.com/drive/folders/'+encodeURIComponent(data.folder_id);q('#drive-folder-link').textContent=data.folder_name+' →'}q('#callback-url').textContent=data.redirect_uri||oauth.elements.redirect_uri.value;q('#missing-settings').textContent=data.missing.length?'Не заданы: '+data.missing.join(', '):'Параметры подключения сохранены '+(data.config_source==='settings'?'через настройки сайта.':'в окружении сервера.');if(!data.configured)q('#setup-help').open=true;form.elements.retention_days.value=data.retention_days;form.elements.grace_days.value=data.grace_days;q('#events-empty').hidden=!!data.events.length;q('#events').replaceChildren();for(const event of data.events){const item=document.createElement('li'),date=document.createElement('time');date.dateTime=new Date(event.at*1000).toISOString();date.textContent=new Date(event.at*1000).toLocaleString('ru-RU');item.append(date,document.createTextNode(event.message));q('#events').append(item)}q('#connect').disabled=!data.configured;}
 async function action(task){if(busy)return;freeze(true);feedback.textContent='Выполняем…';try{await task()}catch(error){feedback.textContent=error.message}finally{freeze(false)}}
 q('#connect').onclick=()=>action(async()=>{const result=await api('/connect','POST');location.assign(result.url)});
 q('#test').onclick=()=>action(async()=>{try{render(await api('/test','POST'));feedback.textContent='Проверка пройдена. Тестовый файл удалён.'}catch(error){try{render(await api())}catch{}throw error}});
 q('#disconnect').onclick=()=>{if(!confirm('Отключить Google Диск? Архивы в Drive сохранятся.'))return;void action(async()=>{await api('/disconnect','POST');render(await api());feedback.textContent='Подключение отключено. Файлы в Google Drive сохранены.'})};
 oauth.onsubmit=event=>{event.preventDefault();if(snapshot?.connected&&!confirm('Сохранить параметры Google? Если они изменились, потребуется заново подключить диск. Архивы сохранятся.'))return;void action(async()=>{const payload={client_id:oauth.elements.client_id.value.trim(),redirect_uri:oauth.elements.redirect_uri.value.trim()};const secret=oauth.elements.client_secret.value.trim();if(secret)payload.client_secret=secret;render(await api('/oauth-config','PUT',payload));feedback.textContent='Параметры сохранены. Нажмите «Подключить Google Диск», если подключение ещё не выполнено.'})};
 q('#cleanup-save').onclick=()=>{const enabled=q('#cleanup-enabled').checked;if(enabled&&!confirm('Включить очистку? После уведомления, резервного срока и проверки архива исходные файлы будут удаляться с сервера. ZIP останется в Google Drive.'))return;void action(async()=>{render(await api('/cleanup-mode','POST',{enabled}));feedback.textContent=enabled?'Очистка включена. Проверка начнётся в течение минуты.':'Очистка выключена.'})};
 q('#cleanup-refresh').onclick=()=>action(async()=>{render(await api());feedback.textContent='Результаты обновлены.'});
 q('#cleanup-run').onclick=()=>{if(!confirm('Запустить проверку очистки сейчас? Если все условия выполнены, исходники будут удалены.'))return;void action(async()=>{await api('/cleanup-run','POST');render(await api());feedback.textContent='Проверка запущена. Результат появится в журнале после завершения.'})};
 form.onsubmit=event=>{event.preventDefault();void action(async()=>{render(await api('','PUT',{retention_days:Number(form.elements.retention_days.value),grace_days:Number(form.elements.grace_days.value)}));feedback.textContent='Сроки хранения сохранены.'})};
 (async()=>{try{render(await api());window.mountAdminNavigation('settings');q('#settings-content').hidden=false;const result=new URLSearchParams(location.search).get('connection');feedback.textContent=result==='connected'?'Google Диск подключён. Выполните проверку.':result==='invalid'?'Ссылка подключения истекла или открыта в другом сеансе. Повторите подключение.':result==='failed'?'Не удалось подключить Google Диск. Проверьте настройки и журнал.':'';if(result)history.replaceState(null,'',location.pathname)}catch(error){feedback.textContent=error.message}})();
})();
